let empresa_id = $('#input_empresa_id').val();
let usuario_id = $('#input_usuario_id').val();
let empresas_planes = [];
let usuarios_ids = [];
let sucursales = JSON.parse($('#input_sucursales').val().replace(/\\/g, '/').replace(/[\n\t\r]/g, ''));
let usuarios = JSON.parse($('#input_usuarios').val().replace(/\\/g, '/').replace(/[\n\t\r]/g, ''));
let empresa = JSON.parse($('#input_empresa').val().replace(/\\/g, '/').replace(/[\n\t\r]/g, ''));
let planes = JSON.parse($('#input_planes').val().replace(/\\/g, '/').replace(/[\n\t\r]/g, ''));
usuarios_ids = usuarios.map(usuario => usuario.id);
let total_usuarios = usuarios_ids.length;

const ESTADOS_PLANES = {
    'Activo': crearTag({ texto: 'Activo', class: 'tag-tonal-green px-5 py-4'}),
    'Inactivo': crearTag({ texto: 'Inactivo', class: 'tag-tonal-gray px-5 py-4'}),
    'Próximo': crearTag({ texto: 'Próximo', class: 'tag-tonal-purple px-5 py-4'}),
    'Por vencer': crearTag({ texto: 'Por vencer', class: 'tag-tonal-yellow px-5 py-4'}),
    'Vencido': crearTag({ texto: 'Vencido', class: 'tag-tonal-red px-5 py-4'}),
    'Renovando': crearTag({ texto: 'Renovando', class: 'tag-tonal-blue px-5 py-4'}),
};

const ICONOS_PLANES_TIPO = {
    'Selección': 'bi-person-bounding-box',
    'Organizacional': 'bi-diagram-3-fill',
    'Vocacional': 'bi-mortarboard-fill',
};

/**
 * Formatea un valor como moneda COP sin decimales.
 *
 * @param {number|string|null} valor Valor a formatear.
 * @returns {string} Valor en formato COP.
 * @author Sergio Vargas
 */
function formatearCOP(valor) {
    const numero = Number(valor);
    if (!Number.isFinite(numero)) {
        return '$0';
    }
    return numero.toLocaleString('es-CO', {
        style: 'currency',
        currency: 'COP',
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
    });
}

/**
 * Obtiene la data para mostrar en la tabla de planes de la empresa.
 *
 * @returns {void}
 * @author Andres Morales
 * @author Fahibram Cárcamo
 * @author Sergio Vargas
*/
async function traerDatos() {
    try {
        let respuesta = await $.ajax({ method: 'GET', url: `empresas-planes-listado-tabla/${empresa_id}` });
        listarPlanes(respuesta.data.empresas_planes, respuesta.data.sucursales_consumos_agendas, respuesta.data.sucursales_consumos_ofertas_laborales);
        empresas_planes = respuesta.data.empresas_planes;
    } catch (error) {
        console.error(error);
    }
}
traerDatos();

/**
 * Crea el componente html de los planes de la empresa
 *
 * @param {array} empresas_planes Arreglo de datos de empresas-planes de la empresa.
 * @param {array} sucursales_consumos_agendas Arreglo de los conteos de los consumos de agendas de las sucursales de la empresa.
 * @param {array} sucursales_consumos_ofertas_laborales Arreglo de los conteos de los consumos de ofertas laborales de las sucursales de la empresa.
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres Morales
 * @author Jair Carvajal
 * @author Andres González
 * @author Daniel Beltrán
 */
function listarPlanes(empresas_planes, sucursales_consumos_agendas, sucursales_consumos_ofertas_laborales) {
    let contenido = empresas_planes.map(empresa_plan => {
        let consumos_empresas = obtenerConsumos(empresa_plan.consumos);
        let lista_consumos_por_sucursal = listarCantidadConsumosSucursales(empresa_plan, sucursales_consumos_agendas, sucursales_consumos_ofertas_laborales);

        let { plan, fecha_vencimiento, precio, estado, vigencia_dias, unidades, conteo_consumos_vacantes, cantidad_usuarios, consumos } = empresa_plan;

        if (!plan && !empresa_plan.plan_credito) {
            return '';
        }
        let suscripcion_ilimitada = !!fecha_vencimiento;

        let fecha_inicio = diferenciaFechasDias((new Date()).toString(), empresa_plan.fecha_inicio) >= 0
            ? empresa_plan.fecha_inicio
            : (new Date()).toString();

        let dias_restantes = suscripcion_ilimitada
            ? diferenciaFechasDias(fecha_inicio, empresa_plan.fecha_vencimiento, false, false)
            : null;

        let unidades_consumidas = empresa_plan.conteo_consumos_agendas ?? 0;
        let ofertas_laborales_consumidas = empresa_plan.conteo_consumos_ofertas_laborales ?? 0;

        return empresa_plan.plan_credito_id === null ? `
            <div class="card my-5">
                <div class="card-body">
                    <div class="row">
                        <div class="col-auto my-auto">${ESTADOS_PLANES[estado.nombre]}</div>
                        <div class="col-auto my-auto">
                            <p class="m-0 text-body-3"><i class="bi ${ICONOS_PLANES_TIPO[plan.tipo_prueba.nombre]} me-2 text-primary text-body-2"></i>${plan.tipo_prueba.nombre}</p>
                            <p class="m-0 text-headline-3 fw-bolder">${plan.nombre}</p>
                        </div>
                        <div class="col-auto ms-auto my-auto">
                            <p class="m-0 text-body-3">Costo: ${formatearCOP(precio)}</p>
                        </div>
                        <div class="col-auto my-auto">
                            <div class="dropdown">
                                ${crearBoton({
                                    clases: 'btn-outline-primary btn-circle dropdown-toggle',
                                    texto: '<i class="bi bi-three-dots-vertical"></i>',
                                    data: [{ texto: 'bs-toggle', value: 'dropdown' }]
                                })}
                                <div class="dropdown-menu dropdown-menu-start">
                                    <button class="dropdown-item no-visited" onclick="abrirModalSolicitudRenovacionPlan(${plan.id}, '${plan.nombre}')">
                                        Solicitar renovación
                                    </button>
                                    <button class="dropdown-item no-visited" onclick="abrirFacturaPlan('${empresa_plan?.archivos[0]?.id}')">
                                        Ver factura
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="table-responsive mt-4">
                        <table class="table">
                            <tbody>
                                <tr id="contenedor_plan_padre">
                                    <td class="py-0 my-0 border-0">
                                        <div class="card bg-gray-90 border-0">
                                            <div class="card-body py-2">
                                                <div class="row">
                                                    <!-- <div class="col-auto my-auto">
                                                        ${crearBoton({
                                                            clases: 'btn-text-gray text-label-2',
                                                            texto: `Sucursales: ${consumos_empresas.length} <i class="bi bi-caret-down-fill"></i>`,
                                                            onclick: `toggleSucursalesList('${empresa_plan.id + '_' + empresa_plan.plan_id + '_' + empresa_plan.numero_factura}', this)`,
                                                        })}
                                                    </div> -->
                                                    <div class="col my-auto">
                                                        <div class="card bg-white border-0">
                                                            <div class="card-body py-2 px-8">
                                                                <div class="row">
                                                                    <div class="col-4 pe-8" ${crearTooltip({
                                                                        placement: 'top',
                                                                        content: generarTooltipConsumosPruebas(empresa_plan.consumos, unidades_consumidas, empresa_plan.pruebas)
                                                                    })}>
                                                                        ${crearProgressBarTemplate('Unidades', 'box', unidades_consumidas, obtenerLimiteConsumo(empresa_plan, 'unidades'), true)}
                                                                    </div>
                                                                    <div class="col-4 pe-8">
                                                                        ${crearProgressBarTemplate('Vacantes', 'briefcase', conteo_consumos_vacantes, obtenerLimiteConsumo(empresa_plan, 'cantidad_ofertas_laborales'), true)}
                                                                    </div>
                                                                    <div class="col-4">
                                                                        ${crearProgressBarTemplate('Usuarios', 'person', total_usuarios, cantidad_usuarios, true)}
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div class="col-auto my-auto ps-0">
                                                        ${crearBoton({
                                                            tooltip: `${crearTooltip({
                                                                placement: `top`,
                                                                content: `Detalle de consumo`,
                                                                toggle: `popover`,
                                                            })}`,
                                                            clases: 'btn-text-primary btn-circle p-2',
                                                            texto: '<i class="bi bi-eye text-headline-4"></i>',
                                                            onclick: `abrirModalConsumos(${empresa_plan.id}, '${plan.nombre}', '${plan.tipo_prueba.nombre}')`,
                                                        })}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                                ${lista_consumos_por_sucursal}
                            </tbody>
                        </table>
                    </div>
                    <div class="row mt-5">
                        <div class="col-auto">
                            <p class="text-label-2">
                                <span class="me-3"><i class="bi bi-clock me-2"></i>Duración: ${empresa_plan.vigencia_dias ? `${empresa_plan.vigencia_dias} día(s)` : 'Sin vigencia'}</span>
                                <span class="">quedan ${ suscripcion_ilimitada ? `${parseInt(dias_restantes) >= 0 ? `${parseInt(dias_restantes)}` : '0'}` : ''} de ${empresa_plan.vigencia_dias ? `${empresa_plan.vigencia_dias}` : '0'} días</span>
                            </p>
                        </div>
                        <div class="col-auto ms-auto">
                            <p class="text-label-2">
                                <span class="me-4">Vigencia</span>
                                <span class="me-4"><i class="bi bi-circle-fill small-1 text-green-cta me-2"></i>${convertirFecha(empresa_plan.fecha_inicio)}</span>
                                ${ suscripcion_ilimitada ? `<span class=""><i class="bi bi-circle-fill small-1 text-danger me-2"></i>${convertirFecha(empresa_plan.fecha_vencimiento)}</span>` : '' }
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        ` : `
            <div class="card my-5">
                <div class="card-body">
                    <div class="row">
                        <div class="col-auto my-auto">${ESTADOS_PLANES[estado.nombre]}</div>
                        <div class="col-auto my-auto">
                            <p class="m-0 text-body-3"><img src="/iconos/icono_ia_azul.svg" alt="IA" class="me-2">Plan de Créditos</p>
                            <p class="m-0 text-headline-3 fw-bolder">${empresa_plan.plan_credito.nombre}</p>
                        </div>
                        <div class="col-auto ms-auto my-auto">
                            <p class="m-0 text-body-3">Costo: ${formatearCOP(empresa_plan.plan_credito.precio)}</p>
                        </div>
                        <div class="col-auto my-auto">
                            <div class="dropdown">
                                ${crearBoton({
                                    clases: 'btn-outline-primary btn-circle dropdown-toggle',
                                    texto: '<i class="bi bi-three-dots-vertical"></i>',
                                    data: [{ texto: 'bs-toggle', value: 'dropdown' }]
                                })}
                                <div class="dropdown-menu dropdown-menu-start">
                                    <button class="dropdown-item no-visited" onclick="abrirModalSolicitudRenovacionPlan(${empresa_plan.plan_credito.id}, '${empresa_plan.plan_credito.nombre}', 'plan_credito')">
                                        Solicitar renovación
                                    </button>
                                    <button class="dropdown-item no-visited" onclick="abrirFacturaPlan('${empresa_plan?.archivos[0]?.id}')">
                                        Ver factura
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div class="table-responsive mt-4">
                        <table class="table">
                            <tbody>
                                <tr id="contenedor_plan_padre">
                                    <td class="py-0 my-0 border-0">
                                        <div class="card bg-gray-90 border-0">
                                            <div class="card-body py-2">
                                                <div class="row">
                                                    <!-- <div class="col-auto my-auto">
                                                        ${crearBoton({
                                                            clases: 'btn-text-gray text-label-2',
                                                            texto: `Sucursales: ${consumos_empresas.length} <i class="bi bi-caret-down-fill"></i>`,
                                                            onclick: `toggleSucursalesList('${empresa_plan.id + '_' + empresa_plan.plan_id + '_' + empresa_plan.numero_factura}', this)`,
                                                        })}
                                                    </div> -->
                                                    <div class="col my-auto">
                                                        <div class="card bg-white border-0">
                                                            <div class="card-body py-2 px-8">
                                                                <div class="row">
                                                                    <div class="col-4 pe-8">
                                                                        ${crearProgressBarTemplate('Créditos disponibles', '/iconos/icono_ia.svg', empresa_plan.creditos_consumidos ?? 0, empresa_plan.plan_credito.creditos ?? 0, true)}
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div class="col-auto my-auto ps-0">
                                                        ${crearBoton({
                                                            tooltip: `${crearTooltip({
                                                                placement: `top`,
                                                                content: `Ver detalle consumo`,
                                                            })}`,
                                                            clases: 'btn-text-primary btn-circle p-2',
                                                            texto: '<i class="bi bi-eye text-headline-4"></i>',
                                                            onclick: `abrirModalConsumosCreditos(${empresa_plan.empresa_id}, ${empresa_plan.id}, '${empresa_plan.plan_credito.nombre}')`,
                                                        })}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        `;
    }).join('');

    $('#listado-planes').html(contenido);
    inicializarTooltips();
}

/**
 * Crea el componente HTML de los progress bars de los consumos.
 *
 * @param {string} label Etiqueta del progress bar.
 * @param {string} icono Icono del progress bar.
 * @param {number} valor Valor actual del consumo.
 * @param {number} total Valor total del consumo.
 * @param {boolean} un_text Booleano para mostrar o no el texto.
 * @returns {string} HTML del progress bar.
 * @author Andres Morales
 * @author Andres Gonzalez
 */
function crearProgressBarTemplate(label, icono, valor, total, un_text) {
    let icono_html = '';
    if (icono) {
        if (icono.startsWith('/') || icono.includes('.svg')) {
            icono_html = `<img src="${icono}" alt="${label}" class="me-2">`;
        } else {
            icono_html = `<i class="bi bi-${icono} text-headline-5 me-2"></i>`;
        }
    }
    return `
        ${un_text ? '<p class="text-label-1 mb-1">' : ''}${icono_html}${label}${un_text ? '</p>' : ''}
        ${crearProgressBar({
            label: `${valor}/${total ?? 0}`,
            height: '8px',
            porcentaje: { porcentaje: (valor / (total ?? 1)) * 100, texto: false }
        })}
    `;
}

/**
 * Retornar el componente html de la lista de cantidades de consumos agrupados por sucursal.
 *
 * @param {Object} empresa_plan Registro de la tabla empresas_planes.
 * @param {array} sucursales_consumos_agendas Arreglo de los conteos de los consumos de agendas de las sucursales de la empresa.
 * @param {array} sucursales_consumos_ofertas_laborales Arreglo de los conteos de los consumos de ofertas laborales de las sucursales de la empresa.
 * @returns {string}
 * @author Andres Morales
 * @author Fahibram Cárcamo
 * @author Sergio Vargas
 */
function listarCantidadConsumosSucursales (empresa_plan, sucursales_consumos_agendas, sucursales_consumos_ofertas_laborales) {
    if (!empresa_plan.plan) {
        return '';
    }
    return sucursales.map(sucursal => {
        let conteos_consumos_agendas_sucursal = sucursales_consumos_agendas.find(sucursal_busqueda => sucursal_busqueda.id === sucursal.id);
        let conteos_consumos_ofertas_laborales_sucursal = sucursales_consumos_ofertas_laborales.find(sucursal_busqueda => sucursal_busqueda.id === sucursal.id);

        let total_agendas_consumidas_sucursal = conteos_consumos_agendas_sucursal?.consumos_agrupados_por_empresa_plan
            ?.find(conteo => conteo.empresa_plan_id === empresa_plan.id)
            ?.conteo_consumos ?? 0;

        let total_ofertas_laborales_consumidas_sucursal = conteos_consumos_ofertas_laborales_sucursal?.consumos_agrupados_por_empresa_plan
            ?.find(conteo => conteo.empresa_plan_id === empresa_plan.id)
            ?.conteo_consumos ?? 0;

        let total_usuarios_sucursal = obtenerTotalUsuarios(sucursal);
        let plan = empresa_plan.plan;

        return `
            <tr class="contenedor_plan_hijo_${empresa_plan.id}_${plan.id}_${empresa_plan.numero_factura} d-none">
                <td class="py-0 my-0">
                    <div class="card border-0">
                        <div class="card-body py-2 px-10">
                            <div class="row">
                                <div class="col-2 my-auto text-body-3 text-wrap">
                                    ${sucursal.nombre_comercial}
                                </div>
                                <div class="col my-auto">
                                    <div class="card bg-white border-0">
                                        <div class="card-body py-2">
                                            <div class="row">
                                                <div class="col-4 px-7">
                                                    ${
                                                        crearProgressBarTemplate(
                                                            'Unidades',
                                                            'box',
                                                            total_agendas_consumidas_sucursal,
                                                            plan.unidades,
                                                            false
                                                        )
                                                    }
                                                </div>
                                                <div class="col-4 px-7">
                                                    ${
                                                        crearProgressBarTemplate(
                                                            'Vacantes',
                                                            'briefcase',
                                                            total_ofertas_laborales_consumidas_sucursal,
                                                            plan.cantidad_ofertas_laborales,
                                                            false
                                                        )
                                                    }
                                                </div>
                                                <div class="col-4 px-7">
                                                    ${
                                                        crearProgressBarTemplate(
                                                            'Usuarios',
                                                            'person',
                                                            total_usuarios_sucursal,
                                                            plan.cantidad_usuarios,
                                                            false
                                                        )
                                                    }
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

/**
 * Agrupar los consumos de un plan por empresa.
 *
 * @param {Object} empresa_plan_consumos Consumos del registro de la tabla empresas_planes.
 * @returns {array}
 * @author Andres Morales
 */
function obtenerConsumos(empresa_plan_consumos) {
    if (!empresa_plan_consumos || empresa_plan_consumos.length === 0) return sucursales;

    let consumos_empresas = new Map();

    empresa_plan_consumos.forEach(consumo => {
        let empresa = consumo.empresa;
        if (!consumos_empresas.has(empresa.id)) {
            empresa.consumos = [];
            consumos_empresas.set(empresa.id, empresa);
        }
        consumos_empresas.get(empresa.id).consumos.push(consumo);
    });

    sucursales.forEach(sucursal => {
        if (!consumos_empresas.has(sucursal.id)) {
            consumos_empresas.set(sucursal.id, sucursal);
        }
    });

    return Array.from(consumos_empresas.values());
}

/**
 * Retornar la suma total de usuarios de una empresa o de todas las empresas.
 *
 * @param {Object|null} empresa Empresa a la que pertenecen los usuarios.
 * @returns {number}
 * @author Andres Morales
 */
function obtenerTotalUsuarios(empresa = null) {
    let usuarios_temporal = empresa?.usuarios ?? usuarios;
    let usuarios_ids_temporal = new Set();
    usuarios_temporal.forEach(usuario => {
        if (usuarios_ids.includes(usuario.id)) {
            usuarios_ids_temporal.add(usuario.id);
        }
    });
    return usuarios_ids_temporal.size;
}

/**
 * Abrir y cerrar el contenido de la lista de consumos por sucursal.
 *
 * @param {string} id Id del elemento a mostar u ocultar.
 * @param {string} elemento Elemento padre del menú de acciones.
 * @returns {void}
 * @author Andres Morales
 */
function toggleSucursalesList(id, elemento) {
    $('.contenedor_plan_hijo_' + id).toggleClass('d-none');
    $(elemento).find('i').toggleClass('bi-caret-down-fill bi-caret-up-fill');
}

/**
 * Realizar la consulta HTTP para solicitar la renovación de un plan.
 *
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres Morales
 * @author Andres González
 */
async function solicitarRenovacionPlan() {
    $('#modal-solicitar-renovacion').modal('hide');
    let plan_id = $('#id-plan-solicitar-renovacion').val();
    let tipo_plan = $('#tipo-plan-solicitar-renovacion').val();
    await $.ajax({
        type: 'POST',
        url : '/solicitud-renovacion-plan',
        data: {
            plan_id,
            tipo_plan,
            empresa_id,
            usuario_id,
            _token: $('meta[name="csrf-token"]').attr('content')
        }
    }).then(respuesta => {
        $('#nombre-plan-solicitar-renovacion').text('');
        $('#id-plan-solicitar-renovacion').val('');
        $('#tipo-plan-solicitar-renovacion').val('');
        mostrarToast('success', 'Solicitud de renovación de plan realizada');
    }).catch((error) => {
        mostrarToast('danger', 'Ocurrió un error en la solicitud');
    });
}

/**
 * Abrir el modal de confirmación de solicitud de renovación de un plan.
 *
 * @param {number} plan_id Id del plan o plan de créditos.
 * @param {string} nombre_plan Nombre del plan.
 * @param {string} tipo_plan Tipo de plan ('plan' o 'plan_credito').
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres González
 */
function abrirModalSolicitudRenovacionPlan(plan_id, nombre_plan, tipo_plan = 'plan') {
    $('#nombre-plan-solicitar-renovacion').text(nombre_plan);
    $('#id-plan-solicitar-renovacion').val(plan_id);
    $('#tipo-plan-solicitar-renovacion').val(tipo_plan);
    $('#modal-solicitar-renovacion').modal('show');
}

/**
 * Abrir la factura del plan en una nueva pestaña del navegador.
 *
 * @param {number} factura_id Id de la factura.
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres Morales
 */
async function abrirFacturaPlan(factura_id){
    if (factura_id) {
        await $.ajax({
            type: 'GET',
            url: `archivos-abrir/${factura_id}`,
            xhrFields: {responseType: 'blob'},
        })
            .then(respuesta => {
                let ruta_factura = window.URL.createObjectURL(respuesta);
                window.open(ruta_factura, '_blank');
            })
            .catch((error) => {
                mostrarToast('danger', 'Ocurrió un error en la solicitud');
            });
    } else {
        mostrarToast('danger', 'No se encontró la factura');
    }
}

function generarTooltipPruebasPlan(pruebas) {
    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';
    let contenidoPruebas = pruebas.map(prueba => 
        `<div class='d-flex align-items-center gap-2 mb-1'><img src='/imagenes/logos/pruebas/${slugify(prueba.nombre)}.png' width='16' height='16'> ${prueba.nombre}</div>`
    ).join('');
    return `<div class='p-2'><strong>Pruebas</strong>${contenidoPruebas}</div>`;
