/**
 * Crear un tooltip sobre un elemento HTML
 * 
 * @param {object} componente Datos del componente.
 * @returns {string} Información del tooltip.
 * @author José Manuel Jiménez
 */
function crearTooltip(componente) {
    return `
        data-bs-toggle="tooltip"
        data-bs-placement="${componente.placement ? componente.placement : 'top'}"
        data-bs-container="${componente.container ? componente.container : 'body'}"
        data-bs-trigger="${componente.trigger ? componente.trigger : 'hover'}"
        data-bs-html="true"
        data-bs-title="${componente.content}"
    `;
}

/**
 * Mostrar un tooltip sobre un elemento
 * 
 * @param {string} elemento_id id del elemento HTML del tooltip
 * @returns {void}
 * @author José Manuel Jiménez
 */
function mostrarTooltip(elemento_id) {
    let elemento = document.getElementById(elemento_id);
    let tooltip = bootstrap.Tooltip.getOrCreateInstance(elemento, {
        sanitize: false,
        html: true
    });
    tooltip.show();
}

/**
 * Cerrar un tooltip
 * 
 * @param {string} elemento_id id del elemento HTML del tooltip
 * @returns {void}
 * @author José Manuel Jiménez
 */
function cerrarTooltip(elemento_id) {
    let elemento = document.getElementById(elemento_id);
    let tooltip = bootstrap.Tooltip.getInstance(elemento);
    if (tooltip) {
        tooltip.hide();
    }
}

/**
 * Inicializar los tooltips en cualquier momento
 * 
 * @returns {void}
 */
function inicializarTooltips() {
    const tooltipTriggerList = document.querySelectorAll('[data-bs-toggle="tooltip"]');
    const tooltipList = [...tooltipTriggerList].map(tooltipTriggerEl => {
        return new bootstrap.Tooltip(tooltipTriggerEl, {
            sanitize: false,
            html: true
        });
    });
    document.body.addEventListener('click', function (event) {
        const closeTooltipButton = event.target.closest('.close-tooltip');
        if (closeTooltipButton) {
            tooltipList.forEach(tooltip => tooltip.hide());
        }
    });
    $('[data-bs-toggle="tooltip"]').each(function () { new bootstrap.Tooltip(this); });
    if (localStorage.getItem('opcion_menu_storage') != 'cerrado') {
        $('.lista-primary[data-bs-toggle="tooltip"]').each(function () {
            var tooltip_instancia = bootstrap.Tooltip.getInstance(this);
            if (tooltip_instancia) {
                tooltip_instancia.dispose();
            }
        });
    }
}

/**
 * Inicializar los tooltips automaticamente
 * 
 * @returns {void}
 * @author José Manuel Jiménez
 */
document.addEventListener('DOMContentLoaded', function () {
    inicializarTooltips();
});

