        <div class='d-flex justify-content-between mb-1'>
            <span>Unidades consumidas</span>
            <span class='fw-bold'>${totalUnidades ?? 0}</span>
        </div>
        <hr class='my-1'>`;

    consumosPorPrueba.forEach(p => {
        html += `<div class='d-flex justify-content-between mb-1'>
            <span>${p.nombre}</span>
            <span class='fw-bold'>${p.cantidad}</span>
        </div>`;
    });

    html += `</div>`;
    return html;
}
```

Luego en el código donde se genera el tooltip, se usa así:

```javascript
let tooltipContent = generarTooltipConsumosPruebas(consumos, totalUnidades, pruebas);
element.setAttribute('data-bs-title', tooltipContent);
```

Esto evita los problemas de comillas porque el contenido HTML se genera en JavaScript y se asigna directamente al atributo, sin necesidad de escapar comillas. queda es `min-width:200px` que no tiene comillas en su valor, así que no causa problemas. La función maneja correctamente la escapada de caracteres especiales en los nombres de las pruebas y utiliza Bootstrap para el diseño, evitando estilos inline problemáticos.

content.text:
Usa **clases de Bootstrap** en lugar de estilos inline. Así evitas el problema de las comillas por completo.

## Función completa reescrita:

```javascript
function generarTooltipConsumosPruebas(consumos, totalUnidades, pruebas) {
    if (!pruebas || pruebas.length === 0) {
        return 'Sin datos de consumo';
    }

    let consumosPorPrueba = [];
    pruebas.forEach(p => {
        consumosPorPrueba.push({ nombre: p.nombre, cantidad: 0 });
    });

    if (consumos && consumos.length > 0) {
        consumos.forEach(c => {
            if (c.agenda?.prueba?.nombre) {
                let nombre = c.agenda.prueba.nombre;
                let prueba = consumosPorPrueba.find(p => p.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let filas = consumosPorPrueba.map(p => {
        let slug = slugify(p.nombre);
        return `<tr>
            <td class='pe-3'><img src='/imagenes/logos/pruebas/${slug}.png' width='14' height='14' class='me-1'>${p.nombre}</td>
            <td class='text-end'>${p.cantidad}</td>
        </tr>`;
    }).join('');

    return `<table class='w-100'>
        <tr>
            <td>Unidades consumidas</td>
            <td class='text-end fw-bold'>${totalUnidades ?? 0}</td>
        </tr>
        <tr><td colspan='2'><hr class='my-1'></td></tr>
        ${filas}
    </table>`;
}
```

## Ventajas de esta solución:

| Aspecto | Beneficio |
|---------|-----------|
| Sin `style='...'` | No hay comillas que puedan romper el atributo |
| Usa `<table>` | Alineación automática: columna izquierda (texto), columna derecha (números) |
| Clases Bootstrap | `text-end` alinea a la derecha, `fw-bold` para negrita, `me-1`/`pe-3` para espaciado |
| Sin escapes complejos | Solo necesitas escapar si el nombre tiene `<`, `>`, `&` |

Sí, el problema es que pasar HTML complejo a través de un atributo (`data-bs-title="..."`) siempre va a tener problemas con caracteres especiales. 

La solución correcta es **crear el tooltip dinámicamente con JavaScript**, no a través de atributos HTML.

## Solución: Crear función de tooltip personalizado

**1. Agregar esta función en el archivo `planes.js`:**

```javascript
/**
 * Inicializa un tooltip personalizado con contenido HTML complejo.
 * 
 * @param {string} selector Selector del elemento que activa el tooltip.
 * @param {function} contenidoCallback Función que retorna el HTML del tooltip.
 * @returns {void}
 */
function inicializarTooltipConsumos(selector, contenidoCallback) {
    $(document).on('mouseenter', selector, function() {
        let contenido = contenidoCallback($(this).data());

        let tooltip = $(`<div class="tooltip-consumos">
            <div class="tooltip-consumos-contenido">${contenido}</div>
        </div>`);

        $('body').append(tooltip);

        let rect = this.getBoundingClientRect();
        tooltip.css({
            top: rect.top - tooltip.outerHeight() - 8 + window.scrollY,
            left: rect.left + (rect.width / 2) - (tooltip.outerWidth() / 2) + window.scrollX
        });
    });

    $(document).on('mouseleave', selector, function() {
        $('.tooltip-consumos').remove();
    });
}
```

**2. Agregar estos estilos CSS (en tu archivo de estilos o en un `<style>` en la vista):**

