**4. Simplificar la función `generarTooltipConsumosPruebas`:**

```javascript
function generarTooltipConsumosPruebas(consumos, totalUnidades, pruebas) {
    if (!pruebas || pruebas.length === 0) {
        return '<span>Sin datos de consumo</span>';
    }

    let consumosPorPrueba = pruebas.map(p => ({ nombre: p.nombre, cantidad: 0 }));

    if (consumos && consumos.length > 0) {
        consumos.forEach(c => {
            if (c.agenda?.prueba?.nombre) {
                let prueba = consumosPorPrueba.find(p => p.nombre === c.agenda.prueba.nombre);
                if (prueba) prueba.cantidad++;
            }
        });
    }

    let filas = consumosPorPrueba.map(p => {
        let slug = slugify(p.nombre);
        return `<tr>
            <td class="pe-3"><img src="/imagenes/logos/pruebas/${slug}.png" width="14" height="14" class="me-1">${p.nombre}</td>
            <td class="text-end">${p.cantidad}</td>
        </tr>`;
    }).join('');

    return `<table>
        <tr>
            <td>Unidades consumidas</td>
            <td class="text-end fw-bold">${totalUnidades ?? 0}</td>
        </tr>
        <tr><td colspan="2"><hr></td></tr>
        ${filas}
    </table>`;
}
```

**5. Inicializar el tooltip después de `listarPlanes` (al final de la función):**

```javascript
inicializarTooltipConsumos('.tooltip-consumos-trigger', function(data) {
    let consumos = typeof data.consumos === 'string' ? JSON.parse(data.consumos) : data.consumos;
    let pruebas = typeof data.pruebas === 'string' ? JSON.parse(data.pruebas) : data.pruebas;
    return generarTooltipConsumosPruebas(consumos, data.unidades, pruebas);
});
```

